{
  "headline": "FDA's records trace our supply to plants with multiple OAI classifications and warning letters within three years before the shortage posting",
  "headline_cites": ["D15", "D17", "D19", "D22", "D29", "D32", "D38", "D45", "D46", "D53", "D55", "D57", "D60", "D61", "D62", "D64", "D67", "D70"],
  "sentences": [
    {
      "text": "FDA first posted the sodium chloride shortage on 2015-02-17 and as of 2026-10-21 it has been on the list for 140 months.",
      "cites": ["E457", "D82"]
    },
    {
      "text": "Multiple registered plants on our product labels have received OAI classifications and warning letters from FDA within three years before the shortage posting.",
      "cites": ["D15", "D17", "D19", "D22", "D29", "D32", "D38", "D45", "D46", "D53", "D55", "D57", "D60", "D61", "D62", "D64", "D67", "D70"]
    },
    {
      "text": "Baxter Healthcare Corporation plants received OAI classifications on 2012-11-16 (823 days before posting), 2013-01-11 (767 days before), 2013-04-19 (669 days before), 2014-02-11 (371 days before), 2014-03-28 (326 days before), 2015-04-28 (70 days after), 2015-05-01 (73 days after), 2016-02-26 (374 days after), 2016-06-08 (477 days after), and 2016-10-03 (594 days after).",
      "cites": ["D15", "D17", "D19", "D29", "D32", "D45", "D46", "D57", "D61", "D64"]
    },
    {
      "text": "Warning letters were issued to Baxter Healthcare Corporation on 2013-05-31 (627 days before posting), 2014-10-21 (119 days before posting), and 2016-08-25 (555 days after posting).",
      "cites": ["D22", "D38", "D62"]
    },
    {
      "text": "Hospira, Inc. plants received OAI classifications on 2010-01-19, 2011-06-17, 2011-08-04, 2016-06-08, and 2018-08-15, with warning letters on 2010-04-12 and 2017-02-14.",
      "cites": ["E180", "E182", "E184", "E196", "E198", "E189", "E201"]
    },
    {
      "text": "Fresenius Kabi USA, LLC plants received OAI classifications on 2011-07-08, 2013-01-11, and a warning letter on 2012-02-22 (1091 days before posting).",
      "cites": ["E290", "E293", "E300", "D4"]
    },
    {
      "text": "The rule-based best option is to buy from Ionis Pharmaceuticals, Inc., which is not on FDA's shortage list today and operates the IONIS PHARMS INC. plant.",
      "cites": ["D79"]
    }
  ]
}
